36	    36	export const protectedRouteReadyAtom = atom(
37	    37	    (get) => get(baseProtectedRouteReadyAtom),
38	    38	    (_get, set, next: boolean) => {
39	    39	        set(baseProtectedRouteReadyAtom, next)
40	    40	        if (next) set(protectedRouteReadyLatchAtom, true)
41	    41	    },
