43	    43	// Gate ProtectedRoute reads: raw readiness, or a still-live session that was ready before
44	    44	export const protectedRouteLatchedReadyAtom = atom(
45	    45	    (get) =>
46	    46	        get(baseProtectedRouteReadyAtom) ||
47	    47	        (get(protectedRouteReadyLatchAtom) && get(sessionExistsAtom)),
