51	    51	export const parseInviteFromUrl = (url: URL): InvitePayload | null => {
52	    52	    const token = url.searchParams.get("token")?.trim()
53	    53	    if (!token) return null
54	    54	
55	    55	    const invite: InvitePayload = {token}
56	    56	    const fields: (keyof InvitePayload)[] = [
57	    57	        "email",
58	    58	        "organization_id",
59	    59	        "workspace_id",
60	    60	        "project_id",
61	    61	        "survey",
62	    62	    ]
63	    63	
64	    64	    fields.forEach((field) => {
65	    65	        const value = url.searchParams.get(field)?.trim()
66	    66	        if (value) {
67	    67	            invite[field] = field === "email" ? value.toLowerCase() : value
68	    68	        }
69	    69	    })
70	    70	
71	    71	    return invite
72	    72	}
