74	    74	export const readInviteFromStorage = (): InvitePayload | null => {
75	    75	    if (!isBrowser) return null
76	    76	    try {
77	    77	        const raw = window.localStorage.getItem(INVITE_STORAGE_KEY)
78	    78	        if (!raw) return null
79	    79	        const parsed = JSON.parse(raw)
80	    80	        if (parsed && typeof parsed.token === "string" && parsed.token.trim()) {
81	    81	            return {
82	    82	                token: parsed.token.trim(),
83	    83	                email: typeof parsed.email === "string" ? parsed.email.toLowerCase() : undefined,
84	    84	                organization_id:
85	    85	                    typeof parsed.organization_id === "string" ? parsed.organization_id : undefined,
86	    86	                workspace_id:
87	    87	                    typeof parsed.workspace_id === "string" ? parsed.workspace_id : undefined,
88	    88	                project_id: typeof parsed.project_id === "string" ? parsed.project_id : undefined,
89	    89	                survey: typeof parsed.survey === "string" ? parsed.survey : undefined,
90	    90	            }
91	    91	        }
92	    92	    } catch (error) {
93	    93	        console.error("Failed to read invite from storage:", error)
94	    94	    }
95	    95	    return null
96	    96	}
