98	    98	export const persistInviteToStorage = (invite: InvitePayload | null) => {
99	    99	    if (!isBrowser) return
100	   100	    try {
101	   101	        if (invite && invite.token) {
102	   102	            window.localStorage.setItem(INVITE_STORAGE_KEY, JSON.stringify(invite))
103	   103	        } else {
104	   104	            window.localStorage.removeItem(INVITE_STORAGE_KEY)
105	   105	        }
106	   106	    } catch (error) {
107	   107	        console.error("Failed to persist invite to storage:", error)
108	   108	    }
109	   109	}
