120	   120	/**
121	   121	 * Fully forget a pending invite: clear the atom, storage, and the invite query
122	   122	 * params from the URL. Stripping the URL params matters — `syncAuthStateFromUrl`
123	   123	 * re-seeds storage from the URL, so clearing storage alone would let the invite
124	   124	 * resurrect and bounce the user back to /workspaces/accept.
125	   125	 */
126	   126	export const clearInvite = () => {
127	   127	    const store = getDefaultStore()
128	   128	    store.set(activeInviteAtom, null)
129	   129	    persistInviteToStorage(null)
130	   130	
131	   131	    if (!isBrowser) return
132	   132	    try {
133	   133	        const url = new URL(window.location.href)
134	   134	        let changed = false
135	   135	        INVITE_URL_PARAMS.forEach((param) => {
136	   136	            if (url.searchParams.has(param)) {
137	   137	                url.searchParams.delete(param)
138	   138	                changed = true
139	   139	            }
140	   140	        })
141	   141	        if (changed) {
142	   142	            window.history.replaceState(
143	   143	                window.history.state,
144	   144	                "",
145	   145	                `${url.pathname}${url.search}${url.hash}`,
146	   146	            )
147	   147	        }
148	   148	    } catch (error) {
149	   149	        console.error("Failed to clear invite params from URL:", error)
150	   150	    }
151	   151	}
