153	   153	export const isCurrentAcceptRouteForInvite = (appState: any, invite: InvitePayload) => {
154	   154	    if (!appState.pathname?.startsWith("/workspaces/accept")) return false
155	   155	    const tokenParam = appState.query?.token
156	   156	    const currentToken = Array.isArray(tokenParam) ? tokenParam[0] : tokenParam
157	   157	    return currentToken === invite.token
158	   158	}
