160	   160	export const writePostSignupPending = () => {
161	   161	    if (!isBrowser) return
162	   162	    try {
163	   163	        window.sessionStorage.setItem(POST_SIGNUP_PENDING_KEY, JSON.stringify({ts: Date.now()}))
164	   164	    } catch {
165	   165	        // ignore storage failures
166	   166	    }
167	   167	}
168	   168	
169	   169	const readPostSignupPending = (): boolean => {
170	   170	    if (!isBrowser) return false
171	   171	    try {
172	   172	        const raw = window.sessionStorage.getItem(POST_SIGNUP_PENDING_KEY)
173	   173	        if (!raw) return false
174	   174	        const parsed = JSON.parse(raw) as {ts?: number}
175	   175	        if (!parsed?.ts) return false
176	   176	        if (Date.now() - parsed.ts > POST_SIGNUP_TTL_MS) return false
177	   177	        return true
178	   178	    } catch {
179	   179	        return false
180	   180	    }
181	   181	}
182	   182	
183	   183	const clearPostSignupPending = () => {
184	   184	    if (!isBrowser) return
185	   185	    try {
186	   186	        window.sessionStorage.removeItem(POST_SIGNUP_PENDING_KEY)
187	   187	    } catch {
188	   188	        // ignore storage failures
189	   189	    }
190	   190	}
