192	   192	export const syncAuthStateFromUrl = (nextUrl?: string) => {
193	   193	    if (!isBrowser) return
194	   194	
195	   195	    try {
196	   196	        const store = getDefaultStore()
197	   197	        const url = new URL(nextUrl ?? window.location.href, window.location.origin)
198	   198	        const appState = store.get(appStateSnapshotAtom)
199	   199	        const sessionLoading = store.get(sessionLoadingAtom)
200	   200	        const isSignedIn = store.get(sessionExistsAtom)
201	   201	        const user = store.get(userAtom)
202	   202	        const urlState = store.get(urlAtom)
203	   203	
204	   204	        const resolvedPath = nextUrl ? url.pathname : (appState.pathname ?? url.pathname)
205	   205	        const resolvedAsPath = nextUrl
206	   206	            ? `${url.pathname}${url.search}${url.hash}`
207	   207	            : (appState.asPath ?? `${url.pathname}${url.search}${url.hash}`)
208	   208	        const path = resolvedPath
209	   209	        const asPath = resolvedAsPath
210	   210	        const isAuthRoute = path.startsWith("/auth")
211	   211	        // Next's matched route: the parsed snapshot holds the literal URL, never "/404".
212	   212	        const isNotFoundRoute = Router.pathname === "/404"
213	   213	        const isAuthCallbackRoute = path.startsWith("/auth/callback")
214	   214	        const isAcceptRoute = path.startsWith("/workspaces/accept")
215	   215	        const isPostSignupRoute = path.startsWith("/post-signup")
216	   216	        const authError =
217	   217	            typeof appState.query?.auth_error === "string" ? appState.query.auth_error : null
218	   218	        const baseAppURL = urlState.baseAppURL || "/w"
219	   219	
220	   220	        let invite = parseInviteFromUrl(url)
221	   221	        if (invite) {
222	   222	            persistInviteToStorage(invite)
223	   223	        } else {
224	   224	            const storedInvite = readInviteFromStorage()
225	   225	            if (storedInvite) {
226	   226	                invite = storedInvite
227	   227	            }
228	   228	        }
229	   229	        store.set(activeInviteAtom, invite ?? null)
230	   230	
231	   231	        // Capture a website template deep-link alongside the invite, from the same URL read. Runs
232	   232	        // again on a regional host after a region redirect, since the query string survives the
233	   233	        // switch but the stored key does not.
234	   234	        captureTemplateFromUrl(url)
235	   235	
236	   236	        if (sessionLoading) {
237	   237	            store.set(protectedRouteReadyAtom, false)
238	   238	            return
239	   239	        }
240	   240	
241	   241	        if (isSignedIn) {
242	   242	            if (isPostSignupRoute) {
243	   243	                console.log("[auth-sync] signed in on /post-signup", {
244	   244	                    path,
245	   245	                    asPath,
246	   246	                    baseAppURL,
247	   247	                })
248	   248	                clearPostSignupPending()
249	   249	            }
250	   250	            if (isAuthCallbackRoute) {
251	   251	                store.set(protectedRouteReadyAtom, false)
252	   252	                return
253	   253	            }
254	   254	            if (isAuthRoute) {
255	   255	                if (readPostSignupPending()) {
256	   256	                    clearPostSignupPending()
257	   257	                    void Router.replace("/post-signup").catch((error) => {
258	   258	                        console.error("Failed to redirect to post-signup:", error)
259	   259	                    })
260	   260	                    store.set(protectedRouteReadyAtom, false)
261	   261	                    return
262	   262	                }
263	   263	            }
264	   264	            if (typeof window !== "undefined") {
265	   265	                const upgradeOrgId = window.localStorage.getItem("authUpgradeOrgId")
266	   266	                const identifiers = store.get(appIdentifiersAtom)
267	   267	                const currentWorkspaceId = identifiers.workspaceId
268	   268	                const upgradePath = upgradeOrgId ? `/w/${encodeURIComponent(upgradeOrgId)}` : null
269	   269	                const alreadyOnUpgradePath =
270	   270	                    Boolean(upgradePath) && path.startsWith(upgradePath as string)
271	   271	
272	   272	                if (upgradeOrgId && alreadyOnUpgradePath) {
273	   273	                    window.localStorage.removeItem("authUpgradeOrgId")
274	   274	                    window.localStorage.removeItem("authUpgradeSessionIdentities")
275	   275	                } else if (upgradeOrgId && upgradeOrgId !== currentWorkspaceId) {
276	   276	                    void Router.replace(`/w/${encodeURIComponent(upgradeOrgId)}`).catch((error) => {
277	   277	                        console.error(
278	   278	                            "Failed to redirect authenticated user to upgrade org:",
279	   279	                            error,
280	   280	                        )
281	   281	                    })
282	   282	                    store.set(protectedRouteReadyAtom, false)
283	   283	                    return
284	   284	                }
285	   285	            }
286	   286	
287	   287	            if (invite && !isAcceptRoute) {
288	   288	                const inviteEmail = invite.email?.toLowerCase() ?? undefined
289	   289	                const userEmail = user?.email?.toLowerCase()
290	   290	                const profileQuery = store.get(profileQueryAtom)
291	   291	                const profileLoading = profileQuery.isPending || profileQuery.isFetching
292	   292	
293	   293	                // If invite has an email but user profile is still loading, wait
294	   294	                // This prevents race conditions where we redirect to accept before
295	   295	                // we can check if the emails match
296	   296	                if (inviteEmail && !userEmail && profileLoading) {
297	   297	                    store.set(protectedRouteReadyAtom, false)
298	   298	                    return
299	   299	                }
300	   300	
301	   301	                if (!inviteEmail || !userEmail || inviteEmail === userEmail) {
302	   302	                    if (!isCurrentAcceptRouteForInvite(appState, invite)) {
303	   303	                        // Spread into a fresh object literal so it satisfies ParsedUrlQueryInput
304	   304	                        void Router.replace({
305	   305	                            pathname: "/workspaces/accept",
306	   306	                            query: {...invite},
307	   307	                        }).catch((error) => {
308	   308	                            console.error("Failed to redirect to invite acceptance:", error)
309	   309	                        })
310	   310	                    }
311	   311	                    store.set(protectedRouteReadyAtom, false)
312	   312	                    return
313	   313	                }
314	   314	                // Invite exists but emails don't match - if on auth route, show the page
315	   315	                // so user can sign out and sign in with the correct account
316	   316	                if (isAuthRoute && inviteEmail && userEmail && inviteEmail !== userEmail) {
317	   317	                    store.set(protectedRouteReadyAtom, true)
318	   318	                    return
319	   319	                }
320	   320	            }
321	   321	
322	   322	            if (isPostSignupRoute) {
323	   323	                store.set(protectedRouteReadyAtom, true)
324	   324	                return
325	   325	            }
326	   326	
327	   327	            if (isAuthRoute) {
328	   328	                if (authError === "sso_denied") {
329	   329	                    if (typeof window !== "undefined") {
330	   330	                        signOut().catch(() => null)
331	   331	                    }
332	   332	                    store.set(protectedRouteReadyAtom, true)
333	   333	                    return
334	   334	                }
335	   335	                // When auth upgrade is required, stay on auth page to show the upgrade message
336	   336	                // The user needs to re-authenticate with the correct method
337	   337	                if (authError === "upgrade_required") {
338	   338	                    store.set(protectedRouteReadyAtom, true)
339	   339	                    return
340	   340	                }
341	   341	                if (typeof window !== "undefined") {
342	   342	                    const upgradeOrgId = window.localStorage.getItem("authUpgradeOrgId")
343	   343	                    if (upgradeOrgId) {
344	   344	                        void Router.replace(`/w/${encodeURIComponent(upgradeOrgId)}`).catch(
345	   345	                            (error) => {
346	   346	                                console.error(
347	   347	                                    "Failed to redirect authenticated user to upgrade org:",
348	   348	                                    error,
349	   349	                                )
350	   350	                            },
351	   351	                        )
352	   352	                        store.set(protectedRouteReadyAtom, false)
353	   353	                        return
354	   354	                    }
355	   355	                }
356	   356	
357	   357	                // IMPORTANT: Don't redirect from /auth here - let usePostAuthRedirect.handleAuthSuccess
358	   358	                // handle the redirect with proper auth method filtering. The auth sync can't filter
359	   359	                // synchronously, so redirecting here would use unfiltered orgs and cause auth upgrade errors.
360	   360	                // The auth components will call handleAuthSuccess which does proper filtering.
361	   361	                console.log(
362	   362	                    "[auth-sync] Signed in user on /auth - letting usePostAuthRedirect handle redirect",
363	   363	                )
364	   364	                store.set(protectedRouteReadyAtom, true)
365	   365	                return
366	   366	            }
367	   367	
368	   368	            if (isAcceptRoute) {
369	   369	                if (!invite) {
370	   370	                    if (!path.startsWith(baseAppURL)) {
371	   371	                        void Router.replace(baseAppURL).catch((error) => {
372	   372	                            console.error("Failed to redirect from empty invite route:", error)
373	   373	                        })
374	   374	                    }
375	   375	                    store.set(protectedRouteReadyAtom, false)
376	   376	                } else {
377	   377	                    // On a wrong-account invite, do NOT redirect away. Let the accept
378	   378	                    // page render its "this invitation is not for you" card with the
379	   379	                    // sign-in-as-different-account action. Redirecting here would bounce
380	   380	                    // the user to their own workspace and hide the explanation.
381	   381	                    store.set(protectedRouteReadyAtom, true)
382	   382	                }
383	   383	            }
384	   384	
385	   385	            if (path === "/w") {
386	   386	                const identifiers = store.get(appIdentifiersAtom)
387	   387	                if (!identifiers.workspaceId) {
388	   388	                    const orgs = store.get(orgsAtom)
389	   389	                    const targetWorkspaceId = resolvePreferredWorkspaceId(user?.id ?? null, orgs)
390	   390	
391	   391	                    if (targetWorkspaceId) {
392	   392	                        const pendingCommand = store.get(navigationRequestAtom)
393	   393	                        if (!pendingCommand) {
394	   394	                            store.set(requestNavigationAtom, {
395	   395	                                type: "href",
396	   396	                                href: `/w/${encodeURIComponent(targetWorkspaceId)}`,
397	   397	                                method: "replace",
398	   398	                            })
399	   399	                        }
400	   400	                        store.set(protectedRouteReadyAtom, false)
401	   401	                        return
402	   402	                    }
403	   403	                }
404	   404	            }
405	   405	
406	   406	            store.set(protectedRouteReadyAtom, true)
407	   407	            return
408	   408	        }
409	   409	
410	   410	        // Signed out: drop the latch so a dead session can never keep the page visible.
411	   411	        // /404 joins the auth screens: bouncing a bad link to sign-in hides the explanation.
412	   412	        if (isAuthRoute || isNotFoundRoute) {
413	   413	            store.set(protectedRouteReadyAtom, true)
414	   414	            store.set(protectedRouteReadyLatchAtom, false)
415	   415	            return
416	   416	        }
417	   417	
418	   418	        const redirectToPath = `/auth?redirectToPath=${encodeURIComponent(asPath)}`
419	   419	        if (asPath !== redirectToPath) {
420	   420	            void Router.replace(redirectToPath).catch((error) => {
421	   421	                console.error("Failed to redirect unauthenticated user to auth:", error)
422	   422	            })
423	   423	        }
424	   424	        store.set(protectedRouteReadyAtom, false)
425	   425	        store.set(protectedRouteReadyLatchAtom, false)
426	   426	    } catch (err) {
427	   427	        console.error("Failed to sync auth state from URL:", nextUrl, err)
428	   428	    }
429	   429	}
