446	    17	// `./playground` and `./variant` drag the heavy workflow/playground graph
447	    18	// (@agenta/entities/workflow, @agenta/playground, playground-ui) into the
448	    19	// always-loaded _app chunk. Load them lazily and replay the latest URL once the
449	    20	// chunk resolves, so non-playground pages never pull them. The sub-second window
450	    21	// before resolution only delays restoring playground/variant-drawer state from a
451	    22	// deep link — every other URL slice stays synchronous.
452	    23	const makeLazyUrlSync = (load: () => Promise<(nextUrl?: string) => void>) => {
453	    24	    let fn: ((nextUrl?: string) => void) | null = null
454	    25	    let loading: Promise<void> | null = null
455	    26	    let pending: {nextUrl?: string} | null = null
456	    27	
457	    28	    return (nextUrl?: string) => {
458	    29	        if (fn) {
459	    30	            fn(nextUrl)
460	    31	            return
461	    32	        }
462	    33	        pending = {nextUrl}
463	    34	        if (!loading) {
464	    35	            loading = load()
465	    36	                .then((resolved) => {
466	    37	                    fn = resolved
467	    38	                    fn(pending?.nextUrl)
468	    39	                    pending = null
469	    40	                })
470	    41	                .catch((error) => {
471	    42	                    loading = null
472	    43	                    console.error("Failed to load lazy URL sync slice:", error)
473	    44	                })
474	    45	        }
475	    46	    }
476	    47	}
