494	    65	const buildQueryFromUrl = (url: URL): ParsedUrlQuery => {
495	    66	    const query: ParsedUrlQuery = {}
496	    67	    url.searchParams.forEach((value, key) => {
497	    68	        if (query[key] === undefined) {
498	    69	            query[key] = value
499	    70	            return
500	    71	        }
501	    72	        if (Array.isArray(query[key])) {
502	    73	            ;(query[key] as string[]).push(value)
503	    74	            return
